import math

r_min, r_max = 2, 10
c_min, c_max = 3, 11

def manhattan_to_frame(r, c):
    """Calculate Manhattan distance from point to the nearest frame 3-cell"""
    d = float('inf')

    # Distance to top row (r_min, all c in [c_min, c_max])
    if r_min <= c <= c_max:
        d = min(d, abs(r - r_min) + abs(c - c))
    else:
        # Closest point on top row is at boundary
        d = min(d, abs(r - r_min) + min(abs(c - c_min), abs(c - c_max)))

    # Distance to bottom row
    if r_max <= c <= c_max:
        d = min(d, abs(r - r_max) + abs(c - c))
    else:
        d = min(d, abs(r - r_max) + min(abs(c - c_min), abs(c - c_max)))

    # Distance to left column
    if r_min <= r <= r_max:
        d = min(d, abs(c - c_min) + abs(r - r))
    else:
        d = min(d, min(abs(c - c_min), abs(c - c_max)) + abs(r - r_min))

    # Distance to right column
    if r_min <= r <= r_max:
        d = min(d, abs(c - c_max) + abs(r - r))
    else:
        d = min(d, min(abs(c - c_min), abs(c - c_max)) + abs(r - r_max))

    return d

# Simpler approach: compute distance to corners and edges
def frame_dist(r, c):
    if r_min <= r <= r_max and c_min <= c <= c_max:
        # Interior or on frame
        return min(
            abs(r - r_min), abs(r - r_max),    # Distance to top/bottom rows
            abs(c - c_min), abs(c - c_max),    # Distance to left/right cols
            0  # If on a frame cell
        ) if (r == r_min or r == r_max or c == c_min or c == c_max) else (
            abs(r - r_min) + min(abs(c - c_min), abs(c - c_max)),
            abs(r - r_max) + min(abs(c - c_min), abs(c - c_max)),
            min(abs(r - r_min), abs(r - r_max)) + abs(c - c_min),
            min(abs(r - r_min), abs(r - r_max)) + abs(c - c_max)
        )
    else:
        # Outside the corridor
        return float('inf')

# Even simpler:
# If r in [r_min+1, r_max-1] and c in [c_min+1, c_max-1], it's interior
# Distance = min(r-r_min, r_max-r, c-c_min, c_max-c) for closest distance to any frame cell

def optimize_fill(r, c):
    if r_min <= r <= r_max and c_min <= c <= c_max:
        # Inside the corridor (including interior)
        if r == r_min or r == r_max or c == c_min or c == c_max:
            return 3  # Frame
        # Interior: use "ring" distance
        horizontal = min(c - c_min, c_max - c)
        vertical = min(r - r_min, r_max - r)
        return 3 if (horizontal == 0 or vertical == 0) else (4 if max(horizontal, vertical) == 1 else 2)
    return 0

